/**
 * Builds one state per triaged burst firing (blastradius/test/replay/account/LAYA-PREREGISTRATION.md).
 * Offline, from the account proof's recorded data. Writes results/states.jsonl (not committed; it is
 * regenerated byte-for-byte by this script, and its sha256 is recorded in results/states.sha256), and
 * results/firings.json (every raw firing of those accounts, for the carry-forward sensitivity analysis).
 *
 *   npx tsx build-states.ts
 */
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { AccountIndex, burstWarnings, type PublishEvent } from '../../blastradius/src/watch/account.ts';
import { runAccountProof } from '../../blastradius/test/replay/account/proof-account.ts';
import { decodeTimelines, type EncodedTimelines } from '../../blastradius/test/replay/account/timelines.ts';

const HERE = dirname(fileURLToPath(import.meta.url));
const DATA = join(HERE, '..', '..', 'blastradius', 'test', 'replay', 'account', 'data');
const OUT = join(HERE, 'results');
const H = 3600_000;
const D = 24 * H;
const W = 6 * H;
const PERIOD: [number, number] = [Date.parse('2025-06-01T00:00:00Z'), Date.parse('2025-12-31T23:59:59Z')];
const RECORDING_START = Date.parse('2025-05-15T00:00:00Z');
const HISTORY = 14 * D;
const MAX_LISTED = 8;

/** Pre-registered split: sha256(name) ascending, first 5 calibration, the rest test. */
export function splitControls(controls: string[]): { calibration: string[]; test: string[] } {
  const h = (s: string) => createHash('sha256').update(s).digest('hex');
  const sorted = [...controls].sort((a, b) => (h(a) < h(b) ? -1 : 1));
  return { calibration: sorted.slice(0, 5), test: sorted.slice(5) };
}

export interface TriagePoint {
  id: string;
  account: string;
  group: 'calibration' | 'test-control' | 'incident';
  incident?: string;
  firedAt: string;
  /** Incident accounts: the firing's window holds a bad-version publish and it is before T0. */
  qualifying?: boolean;
  t0?: string;
  state: BurstState;
}

export interface BurstState {
  event: string;
  account: string;
  window: { distinct_packages: number; publishes: number; span_minutes: number; utc_hour: number };
  account_history_14d: {
    publishes: number;
    distinct_packages: number;
    burst_firings: number;
    share_of_publishes_within_2h_of_this_utc_hour: number | null;
    days_since_first_recorded_publish: number | null;
    note: string;
  };
  aggregates: {
    publisher_new_to_package: number;
    dormant_over_90d: number;
    first_release: number;
    published_by_account_in_prior_14d: number;
    account_sole_maintainer: number;
    median_days_since_previous_release: number | null;
    bump: Record<'major' | 'minor' | 'patch' | 'prerelease' | 'other', number>;
  };
  packages: PackageFacts[];
  more_packages_not_listed: number;
}

interface PackageFacts {
  name: string;
  version: string;
  previous_version: string | null;
  bump: 'major' | 'minor' | 'patch' | 'prerelease' | 'other';
  days_since_previous_release: number | null;
  previous_publishers: string[];
  previous_publishers_total: number;
  publisher_new_to_package: boolean;
  maintainers_before: number | null;
}

const r1 = (x: number) => Math.round(x * 10) / 10;
const median = (xs: number[]) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
};

function bump(prev: string | null, cur: string): PackageFacts['bump'] {
  const p = (v: string) => /^(\d+)\.(\d+)\.(\d+)(-[^+]+)?/.exec(v);
  const c = p(cur);
  if (!c) return 'other';
  if (c[4]) return 'prerelease';
  const q = prev ? p(prev) : null;
  if (!q) return 'other';
  if (c[1] !== q[1]) return 'major';
  if (c[2] !== q[2]) return 'minor';
  if (c[3] !== q[3]) return 'patch';
  return 'other';
}

export function packageFacts(index: AccountIndex, account: string, name: string, version: string, at: number): PackageFacts {
  const tl = index.timeline(name)!;
  const earlier = tl.versions.filter((e) => Date.parse(e.t) < at);
  const prev = earlier.at(-1);
  const pubs = [...new Set(earlier.map((e) => e.u).filter((u): u is string => !!u))];
  const maint = [...earlier].reverse().find((e) => e.m)?.m;
  return {
    name,
    version,
    previous_version: prev?.v ?? null,
    bump: bump(prev?.v ?? null, version),
    days_since_previous_release: prev ? r1((at - Date.parse(prev.t)) / D) : null,
    previous_publishers: pubs.slice(-3),
    previous_publishers_total: pubs.length,
    publisher_new_to_package: !pubs.includes(account),
    maintainers_before: maint ? maint.length : null,
  };
}

export function buildState(index: AccountIndex, account: string, firedAt: number, mine: PublishEvent[], firingsHist: number[]): BurstState {
  const win = mine.filter((e) => e.at > firedAt - W && e.at <= firedAt);
  const firstPer = new Map<string, PublishEvent>();
  for (const e of win) if (!firstPer.has(e.name)) firstPer.set(e.name, e);
  const facts = [...firstPer.values()].map((e) => packageFacts(index, account, e.name, e.version, e.at)).sort((a, b) => a.name.localeCompare(b.name));
  const winStart = firedAt - W;
  const hist = mine.filter((e) => e.at <= winStart && e.at > winStart - HISTORY);
  const hour = new Date(firedAt).getUTCHours();
  const near = hist.filter((e) => {
    const d = Math.abs(new Date(e.at).getUTCHours() - hour);
    return Math.min(d, 24 - d) <= 2;
  }).length;
  const histNames = new Set(hist.map((e) => e.name));
  const first = mine.find((e) => e.at >= RECORDING_START);
  const bumps: BurstState['aggregates']['bump'] = { major: 0, minor: 0, patch: 0, prerelease: 0, other: 0 };
  for (const f of facts) bumps[f.bump]++;
  const sole = [...firstPer.values()].filter((e) => {
    const tl = index.timeline(e.name)!;
    const m = [...tl.versions.filter((v) => Date.parse(v.t) < e.at)].reverse().find((v) => v.m)?.m;
    return m?.length === 1 && m[0] === account;
  }).length;
  return {
    event: `npm account published new versions of ${facts.length} distinct packages within 6 hours`,
    account,
    window: { distinct_packages: facts.length, publishes: win.length, span_minutes: Math.round((win.at(-1)!.at - win[0]!.at) / 60_000), utc_hour: hour },
    account_history_14d: {
      publishes: hist.length,
      distinct_packages: histNames.size,
      burst_firings: firingsHist.filter((t) => t <= winStart && t > winStart - HISTORY).length,
      share_of_publishes_within_2h_of_this_utc_hour: hist.length ? Math.round((near / hist.length) * 100) / 100 : null,
      days_since_first_recorded_publish: first && first.at <= firedAt ? r1((firedAt - first.at) / D) : null,
      note: 'recorded history starts 2025-05-15',
    },
    aggregates: {
      publisher_new_to_package: facts.filter((f) => f.publisher_new_to_package).length,
      dormant_over_90d: facts.filter((f) => f.days_since_previous_release !== null && f.days_since_previous_release > 90).length,
      first_release: facts.filter((f) => f.previous_version === null).length,
      published_by_account_in_prior_14d: facts.filter((f) => histNames.has(f.name)).length,
      account_sole_maintainer: sole,
      median_days_since_previous_release: median(facts.flatMap((f) => (f.days_since_previous_release === null ? [] : [f.days_since_previous_release]))),
      bump: bumps,
    },
    packages: facts.slice(0, MAX_LISTED),
    more_packages_not_listed: Math.max(0, facts.length - MAX_LISTED),
  };
}

/** Hourly triage cadence: first firing of the account, then ≥ 1 h after the previous triaged firing. */
export function triageCadence(firings: number[]): number[] {
  const out: number[] = [];
  for (const t of firings) if (!out.length || t - out.at(-1)! >= H) out.push(t);
  return out;
}

/** Every raw firing of the triaged accounts: [time, window holds a bad-version publish before T0 (incidents)]. */
export type AllFirings = Record<string, [number, 0 | 1][]>;

export async function buildAll(): Promise<{ points: TriagePoint[]; firings: AllFirings; proofEpisodes: Record<string, number>; calibration: string[]; test: string[] }> {
  const proof = await runAccountProof();
  const index = new AccountIndex(decodeTimelines(JSON.parse(readFileSync(join(DATA, 'timelines.json'), 'utf8')) as EncodedTimelines));
  const accounts = JSON.parse(readFileSync(join(DATA, 'accounts.json'), 'utf8')) as Record<string, { role: string }>;
  const controls = Object.keys(accounts).filter((u) => accounts[u]!.role === 'control');
  const { calibration, test } = splitControls(controls);
  const prim = proof.h2.find((r) => r.rule.n === 5 && r.rule.windowH === 6)!;
  const incidents = prim.incidents.filter((i) => i.account === 'qix' || (i.incident.startsWith('shai-hulud') && i.badPackages >= 5));
  const badOf = new Map(incidents.map((i) => [i.account, new Set(proof.h1.find((a) => a.account === i.account && a.incident === i.incident)!.badPackages.flatMap((b) => b.versions.map((v) => `${b.name}@${v}`)))]));

  // Firings exactly as in the proof (events in the control period); history from the recording start.
  const events = index.publishEvents(PERIOD[0], PERIOD[1]).events;
  const wide = index.publishEvents(RECORDING_START, PERIOD[1]).events;
  const firings = burstWarnings(events, { n: 5, windowMs: W, episodeGapMs: 0 });
  const wideFirings = burstWarnings(wide, { n: 5, windowMs: W, episodeGapMs: 0 });
  const points: TriagePoint[] = [];
  const all: AllFirings = {};
  const targets: [string, TriagePoint['group']][] = [...calibration.map((u) => [u, 'calibration'] as [string, TriagePoint['group']]), ...test.map((u) => [u, 'test-control'] as [string, TriagePoint['group']]), ...incidents.map((i) => [i.account, 'incident'] as [string, TriagePoint['group']])];
  for (const [account, group] of targets) {
    const mine = wide.filter((e) => e.account === account);
    const hist = wideFirings.filter((f) => f.account === account).map((f) => f.firedAt);
    const raw = firings.filter((f) => f.account === account).map((f) => f.firedAt);
    const times = triageCadence(raw);
    const inc = incidents.find((i) => i.account === account);
    const qualifies = (t: number) => !!inc && t < Date.parse(inc.t0) && events.some((e) => e.account === account && e.at > t - W && e.at <= t && badOf.get(account)!.has(`${e.name}@${e.version}`));
    all[account] = raw.map((t) => [t, inc && qualifies(t) ? 1 : 0]);
    for (const t of times) {
      const p: TriagePoint = { id: `${account}@${new Date(t).toISOString()}`, account, group, firedAt: new Date(t).toISOString(), state: buildState(index, account, t, mine, hist) };
      if (inc) {
        const bad = badOf.get(account)!;
        p.incident = inc.incident;
        p.t0 = inc.t0;
        p.qualifying = t < Date.parse(inc.t0) && events.some((e) => e.account === account && e.at > t - W && e.at <= t && bad.has(`${e.name}@${e.version}`));
        if (p.qualifying !== qualifies(t)) throw new Error('qualifying mismatch');
      }
      points.push(p);
    }
  }
  const proofEpisodes = Object.fromEntries(prim.controls.map((c) => [c.account, c.episodes]));
  return { points, firings: all, proofEpisodes, calibration, test };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { points, firings, proofEpisodes, calibration, test } = await buildAll();
  mkdirSync(OUT, { recursive: true });
  const body = points.map((p) => JSON.stringify(p)).join('\n') + '\n';
  writeFileSync(join(OUT, 'states.jsonl'), body);
  const sha = createHash('sha256').update(body).digest('hex');
  writeFileSync(join(OUT, 'states.sha256'), `${sha}  states.jsonl\n`);
  writeFileSync(join(OUT, 'firings.json'), `${JSON.stringify(firings)}\n`);
  writeFileSync(join(OUT, 'split.json'), `${JSON.stringify({ calibration, test, proofEpisodes, points: points.length }, null, 1)}\n`);
  const by = new Map<string, number>();
  for (const p of points) by.set(`${p.group} ${p.account}`, (by.get(`${p.group} ${p.account}`) ?? 0) + 1);
  console.log([...by].map(([k, v]) => `${k}: ${v}`).join('\n'));
  console.log(`points ${points.length}, states sha256 ${sha}`);
}
